        # @param link_name Location where the symbolic link will be created (e.g., "/new-file-link").
        # @param expand Replace "${VAR}" or "$VAR" in the value of path according to the current environment variables defined in the container (e.g. "/$VAR/foo.txt").
        def with_symlink(target:, link_name:, expand: nil)
          Container.new(@query.select("withSymlink", target:, linkName: link_name, expand:))
        end

        # Retrieves this container plus the given OCI annotation.
        # @param name The name of the annotation.
        # @param value The value of the annotation.
        def with_annotation(name:, value:)
          Container.new(@query.select("withAnnotation", name:, value:))
        end

        # Retrieves this container minus the given OCI annotation.
        # @param name The name of the annotation.
        def without_annotation(name:)
          Container.new(@query.select("withoutAnnotation", name:))
        end

        # Package the container state as an OCI image, and publish it to a registry
        #
        # Returns the fully qualified address of the published image, with digest
        # @param address The OCI address to publish to  Same format as "docker push". Example: "registry.example.com/user/repo:tag"
        # @param platform_variants Identifiers for other platform specific containers.  Used for multi-platform image.
        # @param forced_compression Force each layer of the published image to use the specified compression algorithm.  If this is unset, then if a layer already has a compressed blob in the engine's cache, that will be used (this can result in a mix of compression algorithms for different layers). If this is unset and a layer has no compressed blob in the engine's cache, then it will be compressed using Gzip.
        # @param media_types Use the specified media types for the published image's layers.  Defaults to "OCI", which is compatible with most recent registries, but "Docker" may be needed for older registries without OCI support.
        # @param registry_service Service to use as the registry endpoint for the image address.  The service will be started only for this push.
        # @param protocol Protocol to use for registry communication.  Defaults to "HTTPS". Use "HTTP" only for plain HTTP registries.
        # @param insecure_skip_tls_verify Allow HTTPS registry communication without verifying the server certificate.
        def publish(address:, platform_variants: nil, forced_compression: nil, media_types: nil, registry_service: nil, protocol: nil, insecure_skip_tls_verify: nil)
          @query.select("publish", address:, platformVariants: platform_variants, forcedCompression: forced_compression, mediaTypes: media_types, registryService: registry_service, protocol:, insecureSkipTLSVerify: insecure_skip_tls_verify).execute
        end

        # The platform this container executes and publishes as.
        def platform
          Platform.new(@query.select("platform").execute)
        end

        # Writes the container as an OCI tarball to the destination file path on the host.
        #
        # It can also export platform variants.
        # @param path Host's destination path (e.g., "./tarball").  Path can be relative to the engine's workdir or absolute.
        # @param platform_variants Identifiers for other platform specific containers.  Used for multi-platform image.
        # @param forced_compression Force each layer of the exported image to use the specified compression algorithm.  If this is unset, then if a layer already has a compressed blob in the engine's cache, that will be used (this can result in a mix of compression algorithms for different layers). If this is unset and a layer has no compressed blob in the engine's cache, then it will be compressed using Gzip.
        # @param media_types Use the specified media types for the exported image's layers.  Defaults to OCI, which is largely compatible with most recent container runtimes, but Docker may be needed for older runtimes without OCI support.
        # @param expand Replace "${VAR}" or "$VAR" in the value of path according to the current environment variables defined in the container (e.g. "/$VAR/foo").
        def export(path:, platform_variants: nil, forced_compression: nil, media_types: nil, expand: nil)
          @query.select("export", path:, platformVariants: platform_variants, forcedCompression: forced_compression, mediaTypes: media_types, expand:).execute
        end

        # Exports the container as an image to the host's container image store.
        # @param name Name of image to export to in the host's store
        # @param platform_variants Identifiers for other platform specific containers.  Used for multi-platform image.
        # @param forced_compression Force each layer of the exported image to use the specified compression algorithm.  If this is unset, then if a layer already has a compressed blob in the engine's cache, that will be used (this can result in a mix of compression algorithms for different layers). If this is unset and a layer has no compressed blob in the engine's cache, then it will be compressed using Gzip.
        # @param media_types Use the specified media types for the exported image's layers.  Defaults to OCI, which is largely compatible with most recent container runtimes, but Docker may be needed for older runtimes without OCI support.
        def export_image(name:, platform_variants: nil, forced_compression: nil, media_types: nil)
          @query.select("exportImage", name:, platformVariants: platform_variants, forcedCompression: forced_compression, mediaTypes: media_types).execute(allow_nil: true)
          nil
        end

        # Package the container state as an OCI image, and return it as a tar archive
        # @param platform_variants Identifiers for other platform specific containers.  Used for multi-platform images.
        # @param forced_compression Force each layer of the image to use the specified compression algorithm.  If this is unset, then if a layer already has a compressed blob in the engine's cache, that will be used (this can result in a mix of compression algorithms for different layers). If this is unset and a layer has no compressed blob in the engine's cache, then it will be compressed using Gzip.
        # @param media_types Use the specified media types for the image's layers.  Defaults to OCI, which is largely compatible with most recent container runtimes, but Docker may be needed for older runtimes without OCI support.
        def as_tarball(platform_variants: nil, forced_compression: nil, media_types: nil)
          File.new(@query.select("asTarball", platformVariants: platform_variants, forcedCompression: forced_compression, mediaTypes: media_types))
        end

        # Reads the container from an OCI tarball.
        # @param source File to read the container from.
        # @param tag Identifies the tag to import from the archive, if the archive bundles multiple tags.
        def import(source:, tag: nil)
          Container.new(@query.select("import", source:, tag:))
        end

        # Attach credentials for future publishing to a registry. Use in combination with publish
        # @param address The image address that needs authentication. Same format as "docker push". Example: "registry.dagger.io/dagger:latest"
        # @param username The username to authenticate with. Example: "alice"
        # @param secret The API key, password or token to authenticate to this registry
        def with_registry_auth(address:, username:, secret:)
          Container.new(@query.select("withRegistryAuth", address:, username:, secret:))
        end

        # Retrieves this container without the registry authentication of a given address.
        # @param address Registry's address to remove the authentication from.  Formatted as [host]/[user]/[repo]:[tag] (e.g. docker.io/dagger/dagger:main).
        def without_registry_auth(address:)
          Container.new(@query.select("withoutRegistryAuth", address:))
        end

        # The unique image reference which can only be retrieved immediately after the 'Container.From' call.
        def image_ref
          @query.select("imageRef").execute
        end

        # Computes and returns the manifest for this container as a File.
        # @param forced_compression Force each layer of the image to use the specified compression algorithm.  If this is unset, then if a layer already has a compressed blob in the engine's cache, that will be used (this can result in a mix of compression algorithms for different layers). If this is unset and a layer has no compressed blob in the engine's cache, then it will be compressed using Gzip.
        # @param media_types Media types to use for image layers. Defaults to OCI.
        def manifest(forced_compression: nil, media_types: nil)
          File.new(@query.select("manifest", forcedCompression: forced_compression, mediaTypes: media_types))
        end

        # Returns the image layer or configuration blob with the given digest as a File.
        # @param id Digest of the layer or configuration blob (e.g. "sha256:abc123...").
        # @param forced_compression Force each layer of the image to use the specified compression algorithm.  If this is unset, then if a layer already has a compressed blob in the engine's cache, that will be used (this can result in a mix of compression algorithms for different layers). If this is unset and a layer has no compressed blob in the engine's cache, then it will be compressed using Gzip.
        # @param media_types Media types to use for image layers. Defaults to OCI.
        def layer(id:, forced_compression: nil, media_types: nil)
          File.new(@query.select("layer", id:, forcedCompression: forced_compression, mediaTypes: media_types))
        end

        # Expose a network port. Like EXPOSE in Dockerfile (but with healthcheck support)
        #
        # Exposed ports serve two purposes:
        #
        # - For health checks and introspection, when running services
        #
        # - For setting the EXPOSE OCI field when publishing the container
        # @param port Port number to expose. Example: 8080
        # @param protocol Network protocol. Example: "tcp"
        # @param description Port description. Example: "payment API endpoint"
        # @param experimental_skip_healthcheck Skip the health check when run as a service.
        def with_exposed_port(port:, protocol: nil, description: nil, experimental_skip_healthcheck: nil)
          Container.new(@query.select("withExposedPort", port:, protocol:, description:, experimentalSkipHealthcheck: experimental_skip_healthcheck))
        end

        # Unexpose a previously exposed port.
        # @param port Port number to unexpose
        # @param protocol Port protocol to unexpose
        def without_exposed_port(port:, protocol: nil)
          Container.new(@query.select("withoutExposedPort", port:, protocol:))
        end

        # Retrieves the list of exposed ports.
        #
        # This includes ports already exposed by the image, even if not explicitly added with dagger.
        def exposed_ports
          @query.select("exposedPorts").execute_object_list(Port)
        end

        # Establish a runtime dependency from a container to a network service.
        #
        # The service will be started automatically when needed and detached when it is no longer needed, executing the default command if none is set.
        #
        # The service will be reachable from the container via the provided hostname alias.
        #
        # The service dependency will also convey to any files or directories produced by the container.
        # @param alias_ Hostname that will resolve to the target service (only accessible from within this container)
        # @param service The target service
        def with_service_binding(alias_:, service:)
          Container.new(@query.select("withServiceBinding", alias: alias_, service:))
        end

        # Set the default command to invoke for the container's terminal API.
        # @param args The args of the command.
        # @param disable_dagger_in_dagger Disable Dagger API access for the executed command. By default, commands can connect to the current Dagger engine.
        # @param insecure_root_capabilities Execute the command with all root capabilities. This is similar to running a command with "sudo" or executing "docker run" with the "--privileged" flag. Containerization does not provide any security guarantees when using this option. It should only be used when absolutely necessary and only with trusted commands.
        # @deprecated Use withShell.
        def with_default_terminal_cmd(args:, disable_dagger_in_dagger: nil, experimental_privileged_nesting: nil, insecure_root_capabilities: nil)
          Container.new(@query.select("withDefaultTerminalCmd", args:, disableDaggerInDagger: disable_dagger_in_dagger, experimentalPrivilegedNesting: experimental_privileged_nesting, insecureRootCapabilities: insecure_root_capabilities))
        end

        # Set the shell used by terminal() and withRun().
        # @param interactive Command arguments for interactive use. Example: ["sh"].
        # @param batch Command arguments for batch use. The script is appended as one argument. Defaults to interactive followed by "-c".
        # @param disable_dagger_in_dagger Disable Dagger API access for the executed command. By default, commands can connect to the current Dagger engine.
        # @param insecure_root_capabilities Give the shell all root capabilities. Use only with trusted commands.
        def with_shell(interactive:, batch: nil, disable_dagger_in_dagger: nil, experimental_privileged_nesting: nil, insecure_root_capabilities: nil)
          Container.new(@query.select("withShell", interactive:, batch:, disableDaggerInDagger: disable_dagger_in_dagger, experimentalPrivilegedNesting: experimental_privileged_nesting, insecureRootCapabilities: insecure_root_capabilities))
        end

        # Return the configured shell command. Defaults to ["sh"].
        # @param batch Return the batch command instead of the interactive command.
        def shell(batch: nil)
          Command.new(@query.select("shell", batch:))
        end

        # Execute a script with the configured batch shell and return the modified container.
        # @param command Script to append to the shell command as one argument.
        # @param shell Override the batch shell arguments. Example: ["bash", "-c"].
        # @param disable_dagger_in_dagger Override whether the shell is denied Dagger API access. Omit to use the configured shell setting.
        # @param insecure_root_capabilities Override whether the shell has all root capabilities.
        def with_run(command:, shell: nil, disable_dagger_in_dagger: nil, experimental_privileged_nesting: nil, insecure_root_capabilities: nil)
          Container.new(@query.select("withRun", command:, shell:, disableDaggerInDagger: disable_dagger_in_dagger, experimentalPrivilegedNesting: experimental_privileged_nesting, insecureRootCapabilities: insecure_root_capabilities))
        end

        # Opens an interactive terminal for this container using its configured default terminal command if not overridden by args (or sh as a fallback default).
        # @param cmd If set, override the container's default terminal command and invoke these command arguments instead.
        # @param disable_dagger_in_dagger Disable Dagger API access for the executed command. By default, commands can connect to the current Dagger engine.
        # @param insecure_root_capabilities Execute the command with all root capabilities. This is similar to running a command with "sudo" or executing "docker run" with the "--privileged" flag. Containerization does not provide any security guarantees when using this option. It should only be used when absolutely necessary and only with trusted commands.
        def terminal(cmd: nil, disable_dagger_in_dagger: nil, experimental_privileged_nesting: nil, insecure_root_capabilities: nil)
          Container.new(@query.select("terminal", cmd:, disableDaggerInDagger: disable_dagger_in_dagger, experimentalPrivilegedNesting: experimental_privileged_nesting, insecureRootCapabilities: insecure_root_capabilities).reevaluate)
        end

        # Configures all GPUs available on the host to be accessible to this container.
        #
        # This currently works with NVIDIA devices only, and requires the engine to run with GPU support enabled.
        def with_gpu
          Container.new(@query.select("withGPU"))
        end

        # Configures the provided list of devices to be accessible to this container.
        #
        # This currently works for Nvidia devices only.
        # @param devices List of devices to be accessible to this container.
        # @deprecated Use "withGPU" instead, which exposes all GPUs available on the host.
        def experimental_with_gpu(devices:)
          Container.new(@query.select("experimentalWithGPU", devices:))
        end

        # Configures all available GPUs on the host to be accessible to this container.
        #
        # This currently works for Nvidia devices only.
        # @deprecated Use "withGPU" instead.
        def experimental_with_all_gp_us
          Container.new(@query.select("experimentalWithAllGPUs"))
        end

        # Turn the container into a Service.
        #
        # Be sure to set any exposed ports before this conversion.
        # @param args Command to run instead of the container's default command (e.g., ["go", "run", "main.go"]).  If empty, the container's default command is used.
        # @param use_entrypoint If the container has an entrypoint, prepend it to the args.
        # @param disable_dagger_in_dagger Disable Dagger API access for the executed command. By default, commands can connect to the current Dagger engine.
        # @param dagger_in_dagger_new_session Connect Dagger clients started by the command to the current engine as new sessions, instead of as clients of the current session. Each connection gets its own session, released when that client closes.  The command reaches the engine through DAGGER_ENGINE, so SDKs run a Dagger CLI: set _EXPERIMENTAL_DAGGER_CLI_BIN to one in the container, or let the SDK download one.  Cannot be combined with "disableDaggerInDagger".
        # @param insecure_root_capabilities Execute the command with all root capabilities. This is similar to running a command with "sudo" or executing "docker run" with the "--privileged" flag. Containerization does not provide any security guarantees when using this option. It should only be used when absolutely necessary and only with trusted commands.
        # @param expand Replace "${VAR}" or "$VAR" in the args according to the current environment variables defined in the container (e.g. "/$VAR/foo").
        # @param no_init If set, skip the automatic init process injected into containers by default.  This should only be used if the user requires that their exec process be the pid 1 process in the container. Otherwise it may result in unexpected behavior.
        def as_service(args: nil, use_entrypoint: nil, disable_dagger_in_dagger: nil, experimental_privileged_nesting: nil, dagger_in_dagger_new_session: nil, insecure_root_capabilities: nil, expand: nil, no_init: nil)
          Service.new(@query.select("asService", args:, useEntrypoint: use_entrypoint, disableDaggerInDagger: disable_dagger_in_dagger, experimentalPrivilegedNesting: experimental_privileged_nesting, daggerInDaggerNewSession: dagger_in_dagger_new_session, insecureRootCapabilities: insecure_root_capabilities, expand:, noInit: no_init))
        end

        # Starts a Service and creates a tunnel that forwards traffic from the caller's network to that service.
        #
        # Be sure to set any exposed ports before calling this api.
        # @param random Bind each tunnel port to a random port on the host.
        # @param ports List of frontend/backend port mappings to forward.  Frontend is the port accepting traffic on the host, backend is the service port.
        # @param args Command to run instead of the container's default command (e.g., ["go", "run", "main.go"]).  If empty, the container's default command is used.
        # @param use_entrypoint If the container has an entrypoint, prepend it to the args.
        # @param disable_dagger_in_dagger Disable Dagger API access for the executed command. By default, commands can connect to the current Dagger engine.
        # @param dagger_in_dagger_new_session Connect Dagger clients started by the command to the current engine as new sessions, instead of as clients of the current session. Each connection gets its own session, released when that client closes.  The command reaches the engine through DAGGER_ENGINE, so SDKs run a Dagger CLI: set _EXPERIMENTAL_DAGGER_CLI_BIN to one in the container, or let the SDK download one.  Cannot be combined with "disableDaggerInDagger".
        # @param insecure_root_capabilities Execute the command with all root capabilities. This is similar to running a command with "sudo" or executing "docker run" with the "--privileged" flag. Containerization does not provide any security guarantees when using this option. It should only be used when absolutely necessary and only with trusted commands.
        # @param expand Replace "${VAR}" or "$VAR" in the args according to the current environment variables defined in the container (e.g. "/$VAR/foo").
        # @param no_init If set, skip the automatic init process injected into containers by default.  This should only be used if the user requires that their exec process be the pid 1 process in the container. Otherwise it may result in unexpected behavior.
        def up(random: nil, ports: nil, args: nil, use_entrypoint: nil, disable_dagger_in_dagger: nil, experimental_privileged_nesting: nil, dagger_in_dagger_new_session: nil, insecure_root_capabilities: nil, expand: nil, no_init: nil)
          @query.select("up", random:, ports:, args:, useEntrypoint: use_entrypoint, disableDaggerInDagger: disable_dagger_in_dagger, experimentalPrivilegedNesting: experimental_privileged_nesting, daggerInDaggerNewSession: dagger_in_dagger_new_session, insecureRootCapabilities: insecure_root_capabilities, expand:, noInit: no_init).execute(allow_nil: true)
          nil
        end
      end
    end
  end
end
